    const form = document.querySelector("#quiz-form");
    const result = document.querySelector("#quiz-result");
    const questionNames = ["question-1", "question-2", "question-3"];

    function getQuestionScore(questionName) {
      const options = Array.from(form.elements[questionName]);
      return options.every((option) => option.checked === (option.dataset.correct === "true"));
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const answeredEveryQuestion = questionNames.every((questionName) => {
        return Array.from(form.elements[questionName]).some((option) => option.checked);
      });

      if (!answeredEveryQuestion) {
        result.textContent = "Choose at least one answer for each question before submitting.";
        result.className = "result error";
        return;
      }

      const score = questionNames.filter(getQuestionScore).length;
      result.textContent = `You scored ${score} out of ${questionNames.length}.`;
      result.className = "result success";
    });
