     <header>
       <p class="eyebrow">Multi-select quiz</p>
       <h1>Computer Languages Quiz</h1>
       <p class="intro">Choose every answer that applies for each question, then submit your selections.</p>
     </header>

     <main id="maincontent" tabindex="-1">
       <section class="quiz-card" aria-labelledby="quiz-heading">
